<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject;

use InvalidArgumentException;

class PlatformIdentityRolesListRef implements \Iterator
{
    public static function fromArray(array $items): self
    {
        foreach ($items as $item) {
            if (!$item instanceof PlatformIdentityRolesItem) {
                throw new InvalidArgumentException("All items must be of type PlatformIdentityRolesItem");
            }
        }
        return new self(...$items);
    }

    private array $roles = [];

    public function __construct(PlatformIdentityRolesItem ...$roles)
    {
        $this->roles = $roles;
    }

    public function current(): PlatformIdentityRolesItem
    {
        return current($this->roles);
    }
    public function key(): int
    {
        return key($this->roles);
    }
    public function next(): void
    {
        next($this->roles);
    }
    public function rewind(): void
    {
        reset($this->roles);
    }
    public function valid(): bool
    {
        return key($this->roles) !== null;
    }
}
